     7→import * as React from 'react';
     8→import { classNames as cx, isClassNameArgument } from './componentUtil.ts';
     9→
    10→/**
    11→ * A function that merges React refs into one.
    12→ * Supports both functions and ref objects created using createRef() and useRef().
    13→ *
    14→ * Usage:
    15→ * ```tsx
    16→ * <div ref={mergeRefs(ref1, ref2, ref3)} />
    17→ * ```
    18→ *
    19→ * @param {(React.Ref<T> | undefined)[]} inputRefs Array of refs
    20→ * @returns {React.Ref<T> | React.RefCallback<T>} Merged refs
    21→ */
    22→export const mergeRefs = <T>(
    23→  ...inputRefs: Array<undefined | React.Ref<T>>
    24→): React.Ref<T> | React.RefCallback<T> => {
    25→  const filteredInputRefs = inputRefs.filter(Boolean);
    26→  
    27→  if (filteredInputRefs.length <= 1) {
    28→    const firstRef = filteredInputRefs[0];
    29→    return firstRef || null;
    30→  }
    31→  
    32→  return (ref) => {
    33→    filteredInputRefs.forEach((inputRef) => {
    34→      if (typeof inputRef === 'function') {
    35→        inputRef(ref);
    36→      } else if (inputRef) {
    37→        inputRef.current = ref;
    38→      }
    39→    });
    40→  };
    41→};
    42→
    43→/**
    44→ * Takes zero or more callbacks, and returns a new callback that applies each callback one by one. Returns the return
    45→ * value of the last callback.
    46→ */
    47→export const mergeCallbacks = <Args extends Array<unknown>, Return = undefined>(
    48→  callbacks: Array<undefined | ((...args: Args) => Return)>
    49→) => (...args: Args): Return => {
    50→  // Note: this always returns the result of the last callback. If we want to instead accumulate the return values
    51→  // we could consider an additional argument callback to merge an array of `Return` values into a single `Return`.
    52→  const returnValue = callbacks.reduce<undefined | Return>(
    53→    (_returnValue, callback) => {
    54→      return typeof callback === 'function' ? callback.apply(null, args) : undefined;
    55→    },
    56→    undefined,
    57→  );
    58→  
    59→  // If there is at least one callback, the return value should be an instance of `Return`. If there is no callback,
    60→  // then the `Return` generic will be inferred as `undefined` anyway.
    61→  return returnValue as Return;
    62→};
    63→
    64→
    65→const chain = (...callbacks: Array<unknown>): ((...args: Array<unknown>) => void) => {
    66→  return (...args: Array<unknown>) => {
    67→    for (const callback of callbacks) {
    68→      if (typeof callback === 'function') {
    69→        callback(...args);
    70→      }
    71→    }
    72→  };
    73→};
    74→
    75→type Props = { [key: string]: unknown };
    76→type PropsArg = Props | null | undefined;
    77→type NullToObject<T> = T extends (null | undefined) ? {} : T;
    78→type TupleTypes<T> = { [P in keyof T]: T[P] } extends { [key: number]: infer V } ? NullToObject<V> : never;
    79→type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends ((k: infer I) => void) ? I : never;
    80→/**
    81→ * Takes zero or more callbacks, and returns a new callback that applies each callback one by one. Returns the return
    82→ * value of the last callback.
    83→ * 
    84→ * Adapted from: https://github.com/adobe/react-spectrum/blob/main/packages/%40react-aria/utils/src/mergeProps.ts
    85→ * Copyright 2020 Adobe. All rights reserved.
    86→ */
    87→export const mergeProps = <T extends Array<PropsArg>>(...args: T): UnionToIntersection<TupleTypes<T>> => {
    88→  // Start with a base clone of the first argument. This is a lot faster than starting
    89→  // with an empty object and adding properties as we go.
    90→  const result: Props = {...args[0]};
    91→  for (let i = 1; i < args.length; i++) {
    92→    const props = args[i];
    93→    for (const key in props) {
    94→      const a = result[key];
    95→      const b = props[key];
    96→      
    97→      // Chain events
    98→      if (
    99→        typeof a === 'function' &&
   100→        typeof b === 'function' &&
   101→        // This is a lot faster than a regex.
   102→        key[0] === 'o' &&
   103→        key[1] === 'n' &&
   104→        key.charCodeAt(2) >= /* 'A' */ 65 &&
   105→        key.charCodeAt(2) <= /* 'Z' */ 90
   106→      ) {
   107→        result[key] = chain(a, b);
   108→      } else if (key === 'className' && isClassNameArgument(a) && isClassNameArgument(b)) {
   109→        result[key] = cx(a, b);
   110→      } else if (key === 'ref') {
   111→        // @ts-ignore
   112→        result[key] = mergeRefs(a, b);
   113→      } else {
   114→        result[key] = b !== undefined ? b : a;
   115→      }
   116→    }
   117→  }
   118→  
   119→  return result as UnionToIntersection<TupleTypes<T>>;
   120→};
