   122→
   123→export const usePrevious = <T>(value: T) => {
   124→  const ref: React.RefObject<null | T> = React.useRef(null);
   125→  React.useEffect(() => {
   126→    ref.current = value;
   127→  });
   128→  return ref.current;
   129→};
   130→
   131→export const useEffectOnce = (fn: () => void) => {
   132→  const isCalledRef = React.useRef(false);
   133→  
   134→  // biome-ignore lint/correctness/useExhaustiveDependencies: Should run only once
   135→  React.useEffect(() => {
   136→    if (!isCalledRef.current) {
   137→      isCalledRef.current = true;
   138→      fn();
   139→    }
   140→  }, []);
   141→};
   142→
   143→export const useEffectAsync = (effect: () => Promise<unknown>, inputs?: undefined | React.DependencyList): void => {
   144→  React.useEffect(() => {
   145→    effect();
   146→    // biome-ignore lint/correctness/useExhaustiveDependencies: We rely on user deps; adding effect triggers unwanted re-runs
   147→  }, inputs);
   148→};
   149→
   150→// Helper hook 'useLazyRef' lazily initializes a ref value without re-running the initializer
   151→// on every render. Passing an expression directly to 'React.useRef()' (e.g. 'React.useRef(fn())')
   152→// would unnecessarily invoke 'fn' on each render, even though the ref value itself is preserved.
   153→// This helper ensures the initializer runs exactly once.
   154→export const useRefWithInitializer = <T>(initializer: () => T) => {
   155→  const ref = React.useRef<null | T>(null);
   156→
   157→  if (ref.current === null) { ref.current = initializer(); }
   158→
   159→  return ref as React.RefObject<T>;
   160→};
