/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import type { NonUndefined } from '../../../util/types.ts';

import * as React from 'react';
import { flushSync } from 'react-dom';
import { mergeCallbacks, mergeRefs } from '../../../util/reactUtil.ts';
import { classNames as cx } from '../../../util/componentUtil.ts';

import { Dialog } from '../../containers/Dialog/Dialog.tsx';
import { ModalProvider, type ModalProviderProps } from '../../util/overlays/modal/ModalProvider.tsx';

import cl from './DialogModal.module.scss';


export { cl as DialogModalClassNames };

export type DialogModalProps = Omit<React.ComponentProps<typeof Dialog>, 'children'> & {
  /** Content of the modal. If a function, will be passed a dialog controller. */
  children?: React.ReactNode | ModalProviderProps['dialog'],

  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** Whether the modal should be active by default. Default: false. */
  activeDefault?: undefined | boolean,

  /** How to display the modal in the viewport. Default: 'center'. */
  display?: undefined | 'center' | 'full-screen' | 'slide-over',

  /** If `display` is `slide-over`, from which side the modal should originate. */
  slideOverPosition?: undefined | 'left' | 'right',

  /** The size of the modal. Note: does not apply to full screen modals. */
  size?: undefined | 'small' | 'medium' | 'large',

  /**
   * A modal trigger to render. Will be passed an `activate` callback to open the modal. Optional, if not specified
   * you can manually trigger the modal through `modalRef` instead.
   */
  trigger?: undefined | ModalProviderProps['children'],

  /** Whether to allow users to close the dialog manually. */
  allowUserClose?: undefined | boolean,

  /** A reference to the modal, for imperative control. */
  modalRef?: undefined | React.Ref<React.ComponentRef<typeof ModalProvider>>,

  /** Any additional props to pass to the modal provider. */
  providerProps?: undefined | Omit<ModalProviderProps, 'children'>,

  /** Whether to render the model inline or with in a portal */
  renderMethod?: undefined | ModalProviderProps['renderMethod'],
};

export type ModalWithSubject<S> = {
  props: Partial<DialogModalProps>,
  subject: undefined | S,
  activateWith: (subject: S | (() => S)) => void,
  deactivate: () => void,
};
/**
 * Utility hook to get a reference to a `DialogModal` for imperative usage. To open, you can call `activate()`, or
 * `activateWith()` if you want to include some subject data to be shown in the modal.
 */
export const useModalWithSubject = <S,>(
  config?: undefined | {
    subjectInitial?: undefined | S | (() => undefined | S),
  },
): ModalWithSubject<S> => {
  const { subjectInitial } = config ?? {};

  const modalRef = ModalProvider.useRef();
  const [subject, setSubject] = React.useState<undefined | S>(subjectInitial);

  return {
    props: {
      modalRef,
    },
    subject,
    activateWith: (subject: S | (() => S)) => {
      // Use flushSync() to force the modal to render, in case the modal rendering is conditional
      // on the subject being set.
      flushSync(() => { setSubject(subject); });

      modalRef.current?.activate();
    },
    deactivate: () => {
      modalRef.current?.deactivate();
    },
  };
};

/**
 * Similar to `useModalWithSubject`, but will be preconfigured for usage as a confirmation modal.
 */
export const useConfirmationModal = <S,>(
  config: {
    subjectInitial?: undefined | S | (() => undefined | S),
    cancelLabel?: undefined | string,
    actionLabel?: undefined | string,
    onCancel?: undefined | ((subject: NonUndefined<S>) => void),
    onConfirm: (subject: NonUndefined<S>) => void,
    cancelActionProps?: undefined | Partial<React.ComponentProps<typeof Dialog.CancelAction>>,
    confirmActionProps?: undefined | Partial<React.ComponentProps<typeof Dialog.SubmitAction>>,
  },
) => {
  const {
    subjectInitial,
    cancelLabel = 'Cancel',
    actionLabel = 'Confirm',
    onConfirm,
    onCancel,
    cancelActionProps = {},
    confirmActionProps = {},
  } = config;
  const modal = useModalWithSubject({ subjectInitial });

  const handleConfirm = React.useCallback(() => {
    const subject = modal.subject;
    if (typeof subject === 'undefined') {
      console.error(`Unexpected: missing subject in confirmation`);
      return;
    }
    onConfirm(subject);
  }, [modal.subject, onConfirm]);

  const handleCancel = React.useCallback(() => {
    const subject = modal.subject;
    if (typeof subject === 'undefined') {
      console.error(`Unexpected: missing subject in confirmation`);
      return;
    }
    onCancel?.(subject);
  }, [modal.subject, onCancel]);

  return {
    ...modal,
    props: {
      ...modal.props,
      // A confirmation modal must use the `role="alertdialog"` rather than the default `role="dialog"`.
      // See: https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/alertdialog_role
      role: 'alertdialog',
      display: 'center' as const,
      size: 'small' as const,
      allowUserClose: false, // Force the user to explicitly select an action
      title: 'Confirm',
      children: 'Are you sure you want to perform this action?',
      actions: (
        <>
          <Dialog.CancelAction
            label={cancelLabel}
            {...cancelActionProps}
            onPress={mergeCallbacks([cancelActionProps.onPress, handleCancel])}
          />
          <Dialog.SubmitAction
            //autoFocus // Focus "confirm" by default?
            label={actionLabel}
            {...confirmActionProps}
            onPress={mergeCallbacks([cancelActionProps.onPress, handleConfirm])}
          />
        </>
      ),
    },
  };
};

/**
 * A dialog component displayed as a modal when activating the given trigger.
 */
export const DialogModal = Object.assign(
  (props: DialogModalProps) => {
    const {
      children,
      unstyled = false,
      activeDefault = false,
      display = 'center',
      slideOverPosition = 'right',
      size = 'medium',
      trigger = () => null,
      allowUserClose = true,
      modalRef,
      providerProps,
      renderMethod = 'portal',
      ...propsRest
    } = props;

    return (
      <ModalProvider
        activeDefault={activeDefault}
        allowUserClose={allowUserClose}
        shouldCloseOnBackdropClick={display !== 'full-screen'}
        renderMethod={renderMethod}
        dialog={dialogController =>
          <Dialog
            aria-modal="true"
            flat={['slide-over'].includes(display)}
            {...dialogController.dialogProps}
            showCloseIcon={allowUserClose}
            autoFocusClose={allowUserClose}
            showCancelAction={allowUserClose}
            onRequestClose={dialogController.close}
            {...propsRest}
            className={cx(
              'bk',
              { [cl['bk-dialog-modal']]: !unstyled },
              { [cl['bk-dialog-modal--center']]: display === 'center' },
              { [cl['bk-dialog-modal--full-screen']]: display === 'full-screen' },
              { [cl['bk-dialog-modal--slide-over']]: display === 'slide-over' },
              { [cl['bk-dialog-modal--slide-over--left']]: display === 'slide-over' && slideOverPosition === 'left' },
              { [cl['bk-dialog-modal--slide-over--right']]: display === 'slide-over' && slideOverPosition === 'right' },
              { [cl['bk-dialog-modal--small']]: size === 'small' },
              { [cl['bk-dialog-modal--medium']]: size === 'medium' },
              { [cl['bk-dialog-modal--large']]: size === 'large' },
              { [cl['bk-dialog-modal--loading']]: propsRest.state === 'loading' },
              dialogController.dialogProps.className,
              propsRest.className,
            )}
          >
            {typeof children === 'function' ? children(dialogController) : children}
          </Dialog>
        }
        {...providerProps}
        ref={mergeRefs(modalRef, providerProps?.ref)}
      >
        {trigger}
      </ModalProvider>
    );
  },
  {
    useModalRef: ModalProvider.useRef,
    useModalWithSubject,
    useConfirmationModal,
    Action: Dialog.Action,
    ActionIcon: Dialog.ActionIcon,
    CancelAction: Dialog.CancelAction,
    SubmitAction: Dialog.SubmitAction,
  },
);

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of the MPL was not
|* distributed with this file, you can obtain one at http://mozilla.org/MPL/2.0/. */

import * as React from 'react';
import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';

import cl from './ProgressBar.module.scss';


export { cl as ProgressBarClassNames };

export type ProgressBarProps = React.PropsWithChildren<ComponentProps<'progress'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** The progress, as a percentage ranging from 0 to 100. */
  progress: number,

  /** An optional label, displayed as the progress bar title. */
  label?: undefined | string,

  /** An optional hint text, displayed below the progress bar. */
  hintText?: undefined | string,
}>;
/**
 * A way to display progress to complete a task or the time remaining.
 */
export const ProgressBar = (props: ProgressBarProps) => {
  const {
    unstyled = false,
    progress = 0,
    label = undefined,
    hintText = undefined,
    ...propsRest
  } = props;
  return (
    <div>
      {label && (
        <div className={cl['bk-progress-bar__label']}>{label}</div>
      )}
      <progress
        {...propsRest}
        className={cx(
          'bk',
          { [cl['bk-progress-bar']]: !unstyled },
          propsRest.className,
        )}
        max={100}
        value={progress}
      >
        {progress}%
      </progress>
      {hintText && (
        <div className={cl['bk-progress-bar__hint-text']}>{hintText}</div>
      )}
    </div>
  );
};

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import { mergeProps } from '../../../../util/reactUtil.ts';

import * as React from 'react';
import { classNames as cx, type ComponentProps } from '../../../../util/componentUtil.ts';

import { Input as InputDefault } from '../Input/Input.tsx';
import {
  type ItemKey,
  type ItemDetails,
  MenuProvider,
} from '../../../overlays/MenuProvider/MenuProvider.tsx';

import cl from './Select.module.scss';


export { cl as SelectClassNames };

export type { ItemKey, ItemDetails };
export type SelectInputProps = ComponentProps<typeof InputDefault>;

/*
A `Select` is a single-select non-editable combobox.

References:
- [1] https://www.w3.org/WAI/ARIA/apg/patterns/combobox
*/

export type SelectProps = Omit<SelectInputProps, 'onSelect'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** A human-readable name for the select. */
  label: string,

  /** Render the given item key as a string label. */
  formatItemLabel?: undefined | ((itemKey: ItemKey) => undefined | string),

  /** The options list to be shown in the dropdown menu. */
  options: React.ComponentProps<typeof MenuProvider>['items'],

  /** A custom `Input` component. */
  Input?: undefined | React.ComponentType<SelectInputProps> & {
    Action?: undefined | React.ComponentType<ComponentProps<typeof InputDefault.Action>>,
  },

  /** The default option to select. Only relevant for uncontrolled usage (i.e. `selected` is `undefined`). */
  defaultSelected?: undefined | null | ItemKey,

  /** The option to select. If `undefined`, this component will be considered uncontrolled. */
  selected?: undefined | null | ItemKey,

  /** Event handler to be called when the selected option state changes. */
  onSelect?: undefined | ((selectedItemKey: null | ItemKey, selectedItemDetails: null | ItemDetails) => void),

  /** Additional props to be passed to the `MenuProvider`. */
  dropdownProps?: undefined | Partial<React.ComponentProps<typeof MenuProvider>>,
};
export const Select = Object.assign(
  (props: SelectProps) => {
    const {
      unstyled = false,
      label,
      formatItemLabel,
      options,
      automaticResize,
      Input = InputDefault,
      // Dropdown props
      defaultSelected,
      selected,
      onSelect,
      dropdownProps = {},
      // Hidden input props
      name,
      form,
      ...propsRest
    } = props;

    const InputAction = Input.Action ?? InputDefault.Action;

    return (
      <MenuProvider
        label={label}
        formatItemLabel={formatItemLabel}
        items={options}
        role="listbox"
        keyboardInteractions="form-control"
        placement="bottom-start"
        offset={0} // Make the dropdown flush with the select element
        defaultSelected={defaultSelected}
        selected={selected}
        onSelect={onSelect}
        {...dropdownProps}
      >
        {({ props, open, requestOpen, selectedOption }) => {
          // @ts-ignore FIXME: `prefix` prop doesn't conform to `HTMLElement` type
          const { ref: anchorRef, ...anchorProps } = props({
            placeholder: 'Select an option',
            'aria-disabled': true,
            readOnly: true, // Make the input non-editable, but still focusable
            ...propsRest,
            className: cx(cl['bk-select'], { [cl['bk-select--open']]: open }, propsRest.className),
            value: selectedOption === null ? '' : selectedOption.label,
            onChange: () => {},
          });

          const propsMerged = mergeProps(
            propsRest,
            anchorProps,
          );

          return (
            <>
              <Input
                role="combobox"
                automaticResize={automaticResize}
                actions={
                  <InputAction
                    // Note: the toggle button should not be focusable, according to:
                    // https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/combobox_role
                    tabIndex={-1}
                    icon="caret-down"
                    className={cx(cl['bk-select__arrow'])}
                    label={open ? 'Close dropdown' : 'Open dropdown'}
                    onPress={() => {}}
                  />
                }
                {...propsMerged}
                inputProps={{
                  ...propsMerged.inputProps,
                  className: cx(cl['bk-select__input'], propsMerged.inputProps?.className),
                }}
                containerProps={{
                  ...propsMerged.containerProps,
                  // Anchor the dropdown to the container, not the inner input
                  ref: anchorRef as React.Ref<HTMLDivElement>,
                }}
              />
              {/* Render a hidden input with the selected option key (rather than the human-readable label). */}
              {typeof name === 'string' &&
                <input type="hidden" form={form} name={name} value={selectedOption?.itemKey ?? ''}/>
              }
            </>
          );
        }}
      </MenuProvider>
    );
  },
  {
    Static: MenuProvider.Static,
    Option: MenuProvider.Option,
    Header: MenuProvider.Header,
    Action: MenuProvider.Action,
    FooterActions: MenuProvider.FooterActions,
  },
);

