import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import * as React from 'react';

import { Banner } from './Banner.tsx';

const meta = {
  component: Banner,
} satisfies Meta<typeof Banner>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Info: Story = {
  render: () => (
    <Banner variant="info" title="Information">
      This is an informational message for the user.
    </Banner>
  ),
  play: async ({ canvas }) => {
    const alert = canvas.getByRole('alert');
    await expect(alert).toBeVisible();
    await expect(canvas.getByText(/information/i)).toBeVisible();
  },
};

export const Warning: Story = {
  render: () => (
    <Banner variant="warning" title="Warning">
      Please review your settings before proceeding.
    </Banner>
  ),
  play: async ({ canvas }) => {
    const alert = canvas.getByRole('alert');
    await expect(alert).toBeVisible();
    await expect(canvas.getByText(/warning/i)).toBeVisible();
  },
};

export const Error: Story = {
  render: () => (
    <Banner variant="error" title="Error occurred">
      The operation failed. Please try again.
    </Banner>
  ),
  play: async ({ canvas }) => {
    const alert = canvas.getByRole('alert');
    await expect(alert).toBeVisible();
    await expect(canvas.getByText(/error occurred/i)).toBeVisible();
  },
};

export const Success: Story = {
  render: () => (
    <Banner variant="success" title="Success">
      Your changes have been saved successfully.
    </Banner>
  ),
  play: async ({ canvas }) => {
    const alert = canvas.getByRole('alert');
    await expect(alert).toBeVisible();
    await expect(canvas.getByText(/success/i)).toBeVisible();
  },
};

export const WithCloseAction: Story = {
  render: () => (
    <Banner variant="info" title="Dismissible banner" showCloseAction onClose={() => {}}>
      This banner can be dismissed by the user.
    </Banner>
  ),
  play: async ({ canvas }) => {
    const alert = canvas.getByRole('alert');
    await expect(alert).toBeVisible();
    const closeButton = canvas.getByRole('button', { name: /close banner/i });
    await expect(closeButton).toBeVisible();
  },
};

